/**
 * auto-header-v3.js — Auto Header Suggestion v3 for Doc2Table (WBS 4.1.1)
 *
 * Implements Owner-approved Auto Header v3 heuristic:
 *
 * Band row definition:
 *   >= 3 horizontal span placeholders AND <= 2 non-empty text cells.
 *   (Two placeholders must NOT trigger the band rule; vertical merges do not count).
 *
 * Rule 1: Top band (group title)
 *   Scan top-down. A band at row 0 with no header yet is a group title;
 *   it (row 0) plus the next physical row (row 1) are header (headers 0-1, data from row 2).
 *   If a top band has no successor, shows a source-linked cannot-suggest warning and keeps prior selections.
 *   Expected: #11, #33, #35, #37, #39, #41 -> headers 0-1, data 2.
 *
 * Rule 2: Label under header
 *   A band row beneath already identified header rows is a label:
 *   its text fills the empty first cell of the column header (or prefixes it if non-empty).
 *   The label row is excluded from the structured data projection; data starts after it.
 *   Raw row stays accessible; provenance on folded text.
 *   Expected: #3 -> header 0, label row 1 folded ("Pressure bar(g)" into cell 0), data from 2.
 *
 * Rule 3: Other top header-like rows
 *   Other consecutive top rows are header-like when all their non-empty text is bold
 *   while the last row is not, OR their source cell count differs from the last row's.
 *   (No non-empty text means the all-text-bold condition is false).
 *   Expected: #44, #52 -> headers 0-1 including (DN), data 2; #14 -> header 0, data 1.
 *
 * Rule 4: Body and no-header
 *   Stop at the first body-like row; do not scan later body rows for headers/bands.
 *   If row 0 is not header-like -> select zero header rows and data from row 0.
 *   Expected: 40 of the 50 eligible tables get no header (e.g. #5, #8, #20, #24, #58, #92, #128).
 *
 * Idempotent: operates on original table data; does not mutate source rows.
 */

(function () {
  'use strict';

  class AutoHeaderV3 {
    /**
     * Compute row statistics for a single normalized row.
     *
     * @param {Object} table   — table object
     * @param {number} rIdx    — row index
     * @returns {Object}       — row statistics
     */
    static getRowStats(table, rIdx) {
      const grid = table.grid || [];
      const row = grid[rIdx] || [];
      const rowMeta = (table.rowMetadata && table.rowMetadata[rIdx]) ? table.rowMetadata[rIdx] : null;

      // Count horizontal span placeholders (cells generated by gridSpan > 1)
      const placeholders = row.filter(c => Boolean(c && c.spanned)).length;

      // Count non-empty text cells
      const nonEmptyCells = row.filter(c => Boolean(c && !c.spanned && c.text && String(c.text).trim().length > 0));
      const nonEmpty = nonEmptyCells.length;

      // Band definition: >= 3 placeholders AND <= 2 non-empty text cells
      const isBand = placeholders >= 3 && nonEmpty <= 2;

      // Source cell count: physical cell count before span expansion
      let sourceCellCount;
      if (rowMeta && typeof rowMeta.sourceCellCount === 'number') {
        sourceCellCount = rowMeta.sourceCellCount;
      } else {
        sourceCellCount = row.filter(c => !c.spanned).length;
      }

      // Bold status:
      // "No non-empty text means the all-text-bold condition is false."
      let hasText = false;
      let allBold = false;

      if (rowMeta && typeof rowMeta.allBold === 'boolean') {
        hasText = rowMeta.hasText;
        allBold = rowMeta.allBold;
      } else {
        if (nonEmptyCells.length > 0) {
          hasText = true;
          // Check if every non-empty cell is bold
          allBold = nonEmptyCells.every(c => Boolean(c.isBold));
        }
      }

      return {
        rIdx,
        placeholders,
        nonEmpty,
        isBand,
        sourceCellCount,
        hasText,
        allBold,
      };
    }

    /**
     * Suggest header rows and data start for a table.
     *
     * @param {Object} table — parsed table object
     * @returns {Object}     — suggestion result
     */
    static suggest(table) {
      if (!table || !table.grid || table.grid.length === 0) {
        return {
          rule: 'Cannot suggest',
          ruleName: 'Empty table',
          ruleExplanation: 'Table has no rows.',
          headerRowCount: 0,
          dataStartRow: 0,
          labelRow: null,
          labelText: null,
          foldedLabel: null,
          affectedRows: [],
          diagnostic: '0 rows',
          warning: true,
        };
      }

      const rowCount = table.rowCount || table.grid.length;

      // Gather row stats for last row
      const lastRowIdx = rowCount - 1;
      const lastRowStats = this.getRowStats(table, lastRowIdx);

      // Gather row stats for row 0
      const r0 = this.getRowStats(table, 0);

      // Check Rule 1: Band at top with no header yet
      if (r0.isBand) {
        if (rowCount < 2) {
          // If top band has no successor, show source-linked cannot-suggest warning
          return {
            rule: 'Cannot suggest',
            ruleName: 'Top band with no successor',
            ruleExplanation: 'Top band at row 0 has no successor row — cannot suggest header. Prior selections kept.',
            headerRowCount: 0,
            dataStartRow: 0,
            labelRow: null,
            labelText: null,
            foldedLabel: null,
            affectedRows: [0],
            diagnostic: 'Top band placeholders: ' + r0.placeholders + ', non-empty: ' + r0.nonEmpty + '; rowCount: 1',
            warning: true,
          };
        }

        // Rule 1 fired: Row 0 is group title, Row 1 is column header
        return {
          rule: 'Rule 1',
          ruleName: 'Rule 1: Top band (group title)',
          ruleExplanation: 'Rule 1: Top band (group title) at row 0 + column header at row 1 -> headers 0-1, data from row 2',
          headerRowCount: 2,
          dataStartRow: 2,
          labelRow: null,
          labelText: null,
          foldedLabel: null,
          affectedRows: [0, 1],
          diagnostic: 'Top band row 0 (placeholders: ' + r0.placeholders + ' >= 3, non-empty: ' + r0.nonEmpty + ' <= 2) + successor row 1',
          warning: false,
        };
      }

      // Check if Row 0 qualifies as header-like under Rule 3
      // Rule 3 condition: all non-empty text is bold while last row is not, OR source cell count differs from last row's
      const r0BoldCondition = r0.allBold && !lastRowStats.allBold;
      const r0CountCondition = r0.sourceCellCount !== lastRowStats.sourceCellCount;
      const r0HeaderLike = r0BoldCondition || r0CountCondition;

      if (!r0HeaderLike) {
        // Rule 4 fired: Stop at first body-like row. Row 0 not header-like -> no header, data from row 0.
        const diagParts = [];
        if (!r0.hasText) diagParts.push('no text');
        else if (!r0.allBold) diagParts.push('not all-bold');
        else if (lastRowStats.allBold) diagParts.push('last row also bold');
        if (!r0CountCondition) diagParts.push('cell count matches last row (' + r0.sourceCellCount + ')');

        return {
          rule: 'Rule 4',
          ruleName: 'Rule 4: Body and no-header',
          ruleExplanation: 'Rule 4: Row 0 not header-like -> zero header rows, data from row 0',
          headerRowCount: 0,
          dataStartRow: 0,
          labelRow: null,
          labelText: null,
          foldedLabel: null,
          affectedRows: [],
          diagnostic: 'Row 0 is body-like (' + diagParts.join(', ') + ')',
          warning: false,
        };
      }

      // Row 0 is header-like under Rule 3. Build diagnostic signals for row 0.
      const r0Signals = [];
      if (r0BoldCondition) r0Signals.push('all-bold');
      if (r0CountCondition) r0Signals.push('cell-count (' + r0.sourceCellCount + ' vs last ' + lastRowStats.sourceCellCount + ')');

      // Now scan row 1 (if table has at least 2 rows)
      if (rowCount >= 2) {
        const r1 = this.getRowStats(table, 1);

        // Check Rule 2: Band row beneath already identified header rows -> label
        if (r1.isBand) {
          // Extract label text from row 1 (concatenate non-empty cell texts)
          const row1Cells = table.grid[1] || [];
          const labelParts = [];
          let labelCol = 0;
          for (let c = 0; c < row1Cells.length; c++) {
            const cell = row1Cells[c];
            if (cell && !cell.spanned && cell.text && String(cell.text).trim().length > 0) {
              labelParts.push(String(cell.text).trim());
              labelCol = c;
            }
          }
          const labelText = labelParts.join(' ');

          return {
            rule: 'Rule 2',
            ruleName: 'Rule 2: Label under header',
            ruleExplanation: 'Rule 2: Header row 0 (' + r0Signals.join(', ') + ') + label row 1 folded ("' + labelText + '"), data from row 2',
            headerRowCount: 1,
            dataStartRow: 2,
            labelRow: 1,
            labelText: labelText,
            foldedLabel: {
              text: labelText,
              labelRow: 1,
              labelCol: labelCol,
              targetRow: 0,
              targetCol: 0,
            },
            affectedRows: [0, 1],
            diagnostic: 'Header row 0 (' + r0Signals.join(', ') + ') + band row 1 (placeholders: ' + r1.placeholders + ') folded into cell 0; row 1 excluded from data',
            warning: false,
          };
        }

        // Check if Row 1 is also header-like under Rule 3
        const r1BoldCondition = r1.allBold && !lastRowStats.allBold;
        const r1CountCondition = r1.sourceCellCount !== lastRowStats.sourceCellCount;
        const r1HeaderLike = r1BoldCondition || r1CountCondition;

        if (r1HeaderLike) {
          const r1Signals = [];
          if (r1BoldCondition) r1Signals.push('all-bold');
          if (r1CountCondition) r1Signals.push('cell-count (' + r1.sourceCellCount + ' vs last ' + lastRowStats.sourceCellCount + ')');

          // Consecutive header rows 0-1
          return {
            rule: 'Rule 3',
            ruleName: 'Rule 3: Other top rows header-like (rows 0-1)',
            ruleExplanation: 'Rule 3: Consecutive header rows 0-1 (row 0: ' + r0Signals.join(', ') + '; row 1: ' + r1Signals.join(', ') + '), data from row 2',
            headerRowCount: 2,
            dataStartRow: 2,
            labelRow: null,
            labelText: null,
            foldedLabel: null,
            affectedRows: [0, 1],
            diagnostic: 'Row 0 (' + r0Signals.join(', ') + ') and Row 1 (' + r1Signals.join(', ') + ') both header-like; data from 2',
            warning: false,
          };
        }

        // Row 1 is body-like. Stop scanning. Header row 0, data from 1.
        return {
          rule: 'Rule 3',
          ruleName: 'Rule 3: Other top rows header-like (row 0)',
          ruleExplanation: 'Rule 3: Header row 0 (' + r0Signals.join(', ') + '), data from row 1',
          headerRowCount: 1,
          dataStartRow: 1,
          labelRow: null,
          labelText: null,
          foldedLabel: null,
          affectedRows: [0],
          diagnostic: 'Row 0 is header-like (' + r0Signals.join(', ') + '); Row 1 is body-like; data from 1',
          warning: false,
        };
      }

      // Single-row table with row 0 header-like
      return {
        rule: 'Rule 3',
        ruleName: 'Rule 3: Other top rows header-like (row 0)',
        ruleExplanation: 'Rule 3: Header row 0 (' + r0Signals.join(', ') + '), data from row 1',
        headerRowCount: 1,
        dataStartRow: 1,
        labelRow: null,
        labelText: null,
        foldedLabel: null,
        affectedRows: [0],
        diagnostic: 'Single-row table: row 0 is header-like (' + r0Signals.join(', ') + ')',
        warning: false,
      };
    }
  }

  // ─── Export ─────────────────────────────────────────────────────────────
  if (typeof window !== 'undefined') {
    window.AutoHeaderV3 = AutoHeaderV3;
  }
  if (typeof module !== 'undefined' && module.exports) {
    module.exports = AutoHeaderV3;
  }

})();
